def solve(inputs: dict) -> float:
    a = inputs['A']
    b = inputs['B']

    total = 0
    for i in range(len(a)):
        quotient = a[i] // b[i]
        print(f"A[{i}] / B[{i}] = {a[i]} / {b[i]} = {quotient}")
        total += quotient

    print(f"Sum = {total}")
    return float(total)

